-- Documentos que el candidato debe subir para un proceso puntual — antes esto era una lista
-- hardcodeada en el frontend (EvalueeForm.jsx) que adivinaba cuáles aplicaban buscando palabras
-- clave en el nombre del proceso (ej. "estudio de seguridad", "poligrafía"), sin ninguna relación
-- real con el catálogo. Ahora un admin los configura por proceso, igual que ya hace con los pasos
-- (procesos_tipos_progreso).
CREATE TABLE "documentos_requeridos_proceso" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_proceso" INTEGER NOT NULL,
  -- Identificador estable del tipo de documento (ej. "cedula", "acta_diploma") — es lo que el
  -- candidato manda como `tipoDocumento` al subir el archivo (ver DocumentoEvaluado.tipoDocumento,
  -- que ya era texto libre desde antes). Único por proceso para no duplicar el mismo documento dos
  -- veces en la misma lista.
  "clave" VARCHAR(100) NOT NULL,
  "nombre" VARCHAR(150) NOT NULL,
  "obligatorio" BOOLEAN NOT NULL DEFAULT true,
  "orden" INTEGER NOT NULL DEFAULT 0,
  UNIQUE ("id_proceso", "clave")
);

ALTER TABLE "documentos_requeridos_proceso"
  ADD FOREIGN KEY ("id_proceso") REFERENCES "procesos" ("id_proceso") ON DELETE CASCADE;
